"""Runtime semantic skill retrieval: one allowed-id list per LLM iteration.

FAISS is queried once per user turn. Each LLM iteration maps those skill ids
to currently legal routable targets so the prompt catalogue and ``activate``
enum stay on the same list.
"""

from __future__ import annotations

import time
from typing import TYPE_CHECKING, Any, Mapping, Optional, Sequence

import structlog

from rasa.mantle.orchestration.set_memory_button import (
    prompt_text_for_set_memory_utterance,
)
from rasa.mantle.skills.catalog import SkillCatalog, routable_target_id_for_skill
from rasa.mantle.state.turn import IncomingTurnTrigger
from rasa.shared.core.events import (
    BotUttered,
    Restarted,
    SessionStarted,
    SkillActivated,
    UserUttered,
)
from rasa.shared.utils.llm import (
    USER,
    sanitize_message_for_prompt,
    tracker_as_readable_transcript,
)

if TYPE_CHECKING:
    from rasa.mantle.model_archive.bootstrap import ModelBootstrap
    from rasa.mantle.state.turn import IncomingTurn
    from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()

PREVIOUSLY_STARTED_UTTERANCE_TURNS = 20


class SkillRetrievalSearchError(Exception):
    """Raised when embed or FAISS search fails at runtime."""


def build_retrieval_query(
    tracker: "DialogueStateTracker",
    user_text: str,
    turns_to_embed: int,
) -> str:
    """Return the FAISS query text for this turn.

    When ``turns_to_embed`` is ``1``, this is the current user message.
    Otherwise it is the last ``turns_to_embed`` utterance lines
    (``UserUttered`` and ``BotUttered``). The current ``UserUttered`` is
    already on the tracker; its line is rewritten to ``user_text`` when
    that stand-in differs, so a suppressed ``set:`` payload is not embedded.
    """
    # Default 1: current message only.
    if turns_to_embed <= 1:
        return user_text
    # Utterance lines only (UserUttered / BotUttered); max_turns is line count.
    # Current UserUttered is already on the tracker when we search.
    raw_user_text = _latest_user_utterance_text(tracker)
    transcript = tracker_as_readable_transcript(
        tracker,
        human_prefix=USER,
        max_turns=turns_to_embed,
        user_utterance_text=_retrieval_user_line,
    )
    if not transcript:
        return user_text
    return _apply_current_user_text(transcript, user_text, raw_user_text)


def _retrieval_user_line(event: UserUttered) -> Optional[str]:
    """Return retrieval text for one user event, omitting a raw ``set:`` payload."""
    return prompt_text_for_set_memory_utterance(event.text or "", event.metadata or {})


def _latest_user_utterance_text(tracker: "DialogueStateTracker") -> str:
    """Return the newest user utterance text, or ``""`` when there is none."""
    for event in reversed(tracker.events):
        if isinstance(event, UserUttered):
            return event.text or ""
    return ""


def _apply_current_user_text(
    transcript: str, user_text: str, raw_user_text: str
) -> str:
    """Align the transcript's current user line with *user_text*.

    When the last line is still the raw utterance, a stand-in replaces it and
    a blank stand-in drops it. A stand-in is appended only when that line was
    omitted. A user line already in the transcript, including one followed by
    an agent line, is left where it is.
    """
    lines = transcript.split("\n") if transcript else []
    prefix = f"{USER}: "
    raw_line = f"{prefix}{sanitize_message_for_prompt(raw_user_text)}"
    stand_in = sanitize_message_for_prompt(user_text)
    stand_in_line = f"{prefix}{stand_in}" if user_text.strip() else ""

    if lines and lines[-1] == raw_line:
        if not stand_in_line:
            lines = lines[:-1]
        elif lines[-1] != stand_in_line:
            lines[-1] = stand_in_line
        return "\n".join(lines)

    if not stand_in_line or stand_in_line in lines or raw_line in lines:
        return transcript
    lines.append(stand_in_line)
    return "\n".join(lines)


def _user_text_for_retrieval(turn: "IncomingTurn") -> str:
    """Return the user text that may be sent to the embedding provider.

    A suppressed turn keeps a raw ``set:`` payload out of the LLM prompt.
    Embedding that payload would bypass the same disclosure control, so use
    the button-title stand-in, or blank when there is none.
    """
    if turn.suppress_llm_user_message:
        return turn.llm_user_message or ""
    return turn.text


async def retrieve_skill_ids_for_turn(
    bootstrap: "ModelBootstrap",
    tracker: "DialogueStateTracker",
    turn: "IncomingTurn",
) -> Optional[tuple[str, ...]]:
    """Return FAISS skill ids for this user turn.

    ``None`` keeps the full legal catalogue. Retrieval is inactive, or load
    attached no index because the catalogue fits in ``num_skills``. ``()``
    means an index is attached and this turn offers no skills from it.

    Raises:
        SkillRetrievalSearchError: Embedding or FAISS search failed.
    """
    if not bootstrap.agent.skill_retrieval.active:
        return None
    store = bootstrap.skills_index
    if store is None:
        return None

    # Silence-timeout turns have empty text. Searching would add embed latency
    # on the voice path and rank neighbours against "". Keep retrieval on
    # (empty FAISS hits) so must-keep still applies.
    if turn.trigger is not IncomingTurnTrigger.USER_MESSAGE:
        return ()

    # Unusable set-memory taps end with a packaged notice and never build
    # the prompt. Embedding the raw ``set:`` payload would be discarded, and
    # a search outage would fail the turn before that notice.
    if turn.skip_set_memory_button_tap:
        return ()

    config = bootstrap.agent.skill_retrieval
    # Current message, or last N utterance lines when turns_to_embed > 1.
    query = build_retrieval_query(
        tracker, _user_text_for_retrieval(turn), config.turns_to_embed
    )
    # A blank query (empty or whitespace user text, and no transcript when
    # turns_to_embed > 1) would rank neighbours against "". Same skip as
    # silence: keep retrieval on so must-keep still applies.
    if not query.strip():
        return ()
    # Top-k neighbours only; no similarity threshold.
    started = time.perf_counter()
    retrieved_skill_ids, similarity_scores = await _search_skill_ids(
        store, query, k=config.num_skills
    )
    duration_ms = round((time.perf_counter() - started) * 1000, 2)
    structlogger.debug(
        "mantle.skill_retrieval.searched",
        skill_count=len(retrieved_skill_ids),
        top_k=config.num_skills,
        retrieved_skill_ids=retrieved_skill_ids,
        similarity_scores=similarity_scores,
        duration_ms=duration_ms,
    )
    return retrieved_skill_ids


def startable_targets_for_retrieved_skills(
    catalog: SkillCatalog,
    memory_values: Mapping[str, Any],
    *,
    active_target_id: Optional[str],
    retrieved_skill_ids: Optional[Sequence[str]],
    tracker: Optional["DialogueStateTracker"] = None,
) -> Optional[tuple[str, ...]]:
    """Intersect retrieved skills with currently legal startable targets.

    Returns ``None`` when this turn is unfiltered, so the prompt and tools stay
    unfiltered. Retrieval is inactive, or the startable catalogue fits in
    ``num_skills``.
    """
    if retrieved_skill_ids is None:
        return None

    # Legal startable set (hidden / disabled / active frame) here so later
    # iterations skip re-embed.
    # Local import: prompts.state imports the agent spec, which imports the
    # tool schemas, which import this module.
    from rasa.mantle.prompts.state import paused_ordered_block_target_ids

    legal = catalog.get_startable_candidate_target_ids(
        dict(memory_values),
        active_target_id=active_target_id,
        paused_block_ids=paused_ordered_block_target_ids(tracker, catalog),
    )
    retrieved_target_ids: set[str] = set()
    for skill_id in retrieved_skill_ids:
        skill = catalog.skill_by_id(skill_id)
        if skill is None:
            continue
        target_id = routable_target_id_for_skill(skill)
        if target_id is not None:
            retrieved_target_ids.add(target_id)
    # FAISS only indexes startable skills. Keep legal internals
    # and call:/@skill handoffs of the live skill even when search missed them.
    must_keep = _must_keep_legal_ids(catalog, legal, active_target_id)
    must_keep.update(_always_include_legal_ids(catalog, legal))
    if tracker is not None:
        must_keep.update(_previously_started_legal_ids(catalog, legal, tracker.events))
    allowed_target_ids = tuple(
        target_id
        for target_id in legal
        if target_id in retrieved_target_ids or target_id in must_keep
    )
    legal_count = len(legal)
    structlogger.debug(
        "mantle.skill_retrieval.allow_list",
        allowed_target_ids=allowed_target_ids,
        retrieved_count=len(retrieved_target_ids),
        must_keep_count=len(must_keep),
        legal_count=legal_count,
        excluded_count=legal_count - len(allowed_target_ids),
    )
    return allowed_target_ids


def apply_allowed_target_ids(
    target_ids: Sequence[str],
    allowed_target_ids: Optional[Sequence[str]],
) -> list[str]:
    """Keep *target_ids* that appear in *allowed_target_ids*, or all when off."""
    if allowed_target_ids is None:
        return list(target_ids)
    allowed = set(allowed_target_ids)
    return [target_id for target_id in target_ids if target_id in allowed]


def _must_keep_legal_ids(
    catalog: SkillCatalog,
    legal: Sequence[str],
    active_target_id: Optional[str],
) -> set[str]:
    """Return legal ids that stay offered while *active_target_id* is live."""
    if not active_target_id:
        return set()
    active_skill = catalog.owning_skill_for_target_id(active_target_id)
    if active_skill is None:
        return set()
    handoff_ids = set(active_skill.referenced_blocks)
    handoff_ids.update(active_skill.referenced_skills)
    keep: set[str] = set()
    for target_id in legal:
        if target_id in handoff_ids:
            keep.add(target_id)
            continue
        owner = catalog.owning_skill_for_target_id(target_id)
        if owner is not None and owner.id == active_skill.id:
            keep.add(target_id)
    return keep


def _always_include_legal_ids(catalog: SkillCatalog, legal: Sequence[str]) -> set[str]:
    """Return legal startable ids for skills marked always-include."""
    return _legal_routable_ids_for_skill_ids(
        catalog,
        legal,
        [
            skill.id
            for skill in catalog.skills.values()
            if skill.always_include_in_prompt
        ],
    )


def _previously_started_legal_ids(
    catalog: SkillCatalog,
    legal: Sequence[str],
    events: Sequence[Any],
) -> set[str]:
    """Return legal startable ids for skills activated in the recent window."""
    return _legal_routable_ids_for_skill_ids(
        catalog,
        legal,
        _activated_skill_ids_in_recent_utterances(
            events, PREVIOUSLY_STARTED_UTTERANCE_TURNS
        ),
    )


def _activated_skill_ids_in_recent_utterances(
    events: Sequence[Any],
    max_utterance_turns: int,
) -> tuple[str, ...]:
    """Return unique skill ids from ``SkillActivated`` in the last utterance turns.

    Stops at ``Restarted`` or ``SessionStarted`` so the window is the current
    conversation, not prior sessions still on the append-only event list.
    """
    skill_ids: list[str] = []
    seen: set[str] = set()
    utterance_turns = 0
    for event in reversed(events):
        if isinstance(event, (Restarted, SessionStarted)):
            break
        if isinstance(event, SkillActivated) and event.skill_id not in seen:
            seen.add(event.skill_id)
            skill_ids.append(event.skill_id)
        if isinstance(event, (UserUttered, BotUttered)):
            utterance_turns += 1
            if utterance_turns > max_utterance_turns:
                break
    return tuple(skill_ids)


def _legal_routable_ids_for_skill_ids(
    catalog: SkillCatalog,
    legal: Sequence[str],
    skill_ids: Sequence[str],
) -> set[str]:
    """Return legal activate targets for the given skill ids.

    Expands each skill to its independently routable target ids, then keeps
    only those that already appear in *legal* so hidden, disabled, and other
    startable filters still apply. Unknown skill ids are skipped.

    Args:
        catalog: Skill catalog used to resolve each skill id.
        legal: Currently startable target ids for this turn.
        skill_ids: Skill ids to map onto activate targets (for example
            always-include or previously started skills).

    Returns:
        The subset of *legal* that belongs to any of *skill_ids*.
    """
    legal_ids = set(legal)
    keep: set[str] = set()
    for skill_id in skill_ids:
        skill = catalog.skill_by_id(skill_id)
        if skill is None:
            continue
        target_id = routable_target_id_for_skill(skill)
        if target_id is not None and target_id in legal_ids:
            keep.add(target_id)
    return keep


async def _search_skill_ids(
    store: Any, query: str, *, k: int
) -> tuple[tuple[str, ...], tuple[float, ...]]:
    """Return unique skill ids and their FAISS scores, best hit first.

    A repeated skill id keeps the first score. Scores are inner-product
    similarities from the index, aligned with the id tuple.
    """
    try:
        results = await store.asimilarity_search_with_score(query, k=k)
    except Exception as exc:
        structlogger.error(
            "mantle.skill_retrieval.search_error",
            error_type=type(exc).__name__,
        )
        raise SkillRetrievalSearchError("Skill retrieval search failed.") from exc
    skill_ids: list[str] = []
    scores: list[float] = []
    seen: set[str] = set()
    for document, score in results:
        metadata = document.metadata or {}
        skill_id = metadata.get("skill_id")
        if not isinstance(skill_id, str) or skill_id in seen:
            continue
        seen.add(skill_id)
        skill_ids.append(skill_id)
        scores.append(float(score))
    return tuple(skill_ids), tuple(scores)
